def find_separator(grid):
    """The index of the row or column that is one color throughout (or the row, preferentially); -1 if none."""
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            return ('row', i)
    for j in range(len(grid[0])):
        if len({row[j] for row in grid}) == 1:
            return ('col', j)
    return (None, -1)

def overlap(grid, color=2):
    """Split the grid on its one-color separator row/column; the two halves overlaid, cells nonzero in both set to color."""
    kind, i = find_separator(grid)
    if kind == 'row':
        a, b = grid[:i], grid[i+1:]
        return [[color if x and y else 0 for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    if kind == 'col':
        a = [r[:i] for r in grid]; b = [r[i+1:] for r in grid]
        return [[color if x and y else 0 for x, y in zip(la, lb)] for la, lb in zip(a, b)]
    return grid
'''
